package br.edu.ifc.treinoecapacitacao.view;
import br.edu.ifc.treinoecapacitacao.App; import br.edu.ifc.treinoecapacitacao.model.Instrutor; import javafx.geometry.*; import javafx.scene.*; import javafx.scene.control.*; import javafx.scene.layout.*; import javafx.stage.Stage;
public class TelaInstrutores { private Stage stage; public TelaInstrutores(Stage stage){this.stage=stage;} public Scene criarCena(){ Label titulo=new Label("Instrutores"); titulo.setId("tituloTreinamentos"); TextField nome=new TextField(), especialidade=new TextField(); nome.setPromptText("Nome"); especialidade.setPromptText("Especialidade"); RadioButton interno=new RadioButton("Interno"), externo=new RadioButton("Externo"); ToggleGroup g=new ToggleGroup(); interno.setToggleGroup(g); externo.setToggleGroup(g); interno.setSelected(true); GridPane form=new GridPane(); form.setHgap(10);form.setVgap(10);form.getStyleClass().add("formulario");form.add(new Label("Nome:"),0,0);form.add(nome,1,0);form.add(new Label("Especialidade:"),0,1);form.add(especialidade,1,1);form.add(new Label("Tipo:"),0,2);form.add(new HBox(10,interno,externo),1,2); ListView<Instrutor> lista=new ListView<Instrutor>(App.instrutores);lista.setPrefHeight(220); Button cadastrar=new Button("Cadastrar");cadastrar.getStyleClass().add("botao-principal");Button voltar=new Button("Voltar"); cadastrar.setOnAction(e->{if(nome.getText().isBlank()){new Alert(Alert.AlertType.WARNING,"Informe o nome.").show();return;}Instrutor i=new Instrutor(nome.getText(),especialidade.getText(),externo.isSelected()?"Externo":"Interno");App.instrutores.add(i);App.historico.add("Instrutor cadastrado: "+i.getNome());nome.clear();especialidade.clear();interno.setSelected(true);}); voltar.setOnAction(e->{stage.setScene(new TelaDashboard(stage).criarCena());stage.setTitle("Painel - Treinamento e Capacitação");}); VBox raiz=new VBox(12,titulo,form,new HBox(8,cadastrar,voltar),lista);raiz.setPadding(new Insets(25));raiz.setAlignment(Pos.TOP_CENTER);Scene scene=new Scene(raiz,650,520);scene.getStylesheets().add("/css/style.css");return scene;} }
